python - <<'PY'
from pathlib import Path
import re
for path in Path('.').rglob('*.proto'):
    text = path.read_text(errors='replace')
    if re.search(r'\brpc\s+Transcribe\b', text):
        print(path)
        lines = text.splitlines()
        for i, line in enumerate(lines):
            if re.search(r'\brpc\s+Transcribe\b', line):
                lo=max(0,i-20); hi=min(len(lines),i+8)
                for n in range(lo,hi): print(f'{n+1}:{lines[n]}')
